// Kendaraan.java
public class Kendaraan {
    private String merek;
    private int roda;

    public Kendaraan(String merek, int roda) {
        this.merek = merek;
        this.roda = roda;
    }

    public String getMerek() {
        return merek;
    }

    public int getRoda() {
        return roda;
    }

    public String info() {
        return merek + " (" + roda + " roda)";
    }
}

contoh.Motor.java:
// Motor.java
public class Motor extends Kendaraan {
    public Motor(String merek) {
        super(merek, 2);
    }
}

contoh.Mobil.java:
// Mobil.java
public class Mobil extends Kendaraan {
    private int pintu;

    public Mobil(String merek, int pintu) {
        super(merek, 4);
        this.pintu = pintu;
    }

    public int getPintu() {
        return pintu;
    }

    @Override
    public String info() {
        return super.info() + ", " + pintu + " pintu";
    }
}

